/* Three-phase interface. All generated content is an explicitly labeled local example. */
paths.planning=paths.projects;paths.architecture=paths.workspaces;paths.meetings=paths.teams;paths.usage=paths.dashboard;
let meetLinkValue='',plans={},architectures={},usageEvents=[],meetingDemo={running:false,lines:[],timer:null,target:'bn',project:null},chartRange=7;
const oldCapture=captureReq;
captureReq=function(){oldCapture();let p=plans[selected],a=architectures[selected];if(p&&$('#planNotes')&&!p.approved)p.notes=$('#planNotes').value;if(a&&$('#architectureDoc')&&!a.approved)a.doc=$('#architectureDoc').value;};
openProject=function(id){captureReq();selected=id;navigate('requirements')};
setTab=function(n){captureReq();document.getElementById(['capture','clarification','specification','quality','baseline'][n])?.scrollIntoView({behavior:'smooth',block:'start'})};
function track(action,phase){usageEvents.push({action,phase,project:selected,space:workspace,time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})})}
function projectPicker(){return '<label class="project-picker">Project<select aria-label="Current project" onchange="captureReq();selected=Number(this.value);render()">'+projects.filter(p=>p.space===workspace).map(p=>'<option value="'+p.id+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label>'}
function projectReady(){if(!projects.some(p=>p.id===selected&&p.space===workspace))selected=projects.find(p=>p.space===workspace)?.id||0;return !!selected}
function workflowHeader(n,title,desc){const r=current(),p=plans[selected],a=architectures[selected];return heading(title,desc,projectPicker())+'<div class="phase-road">'+[['requirements','01','Requirements',r?.approved],['planning','02','Planning',p?.approved],['architecture','03','Architecture',a?.approved]].map(([route,num,name,done],i)=>'<a href="#'+route+'" class="'+(i===n?'current':'')+'"><span class="step-number">'+(done?'✓':num)+'</span><div><b>'+name+'</b><small>'+ (done?'Baseline approved':i===n?'You are here':'Open phase')+'</small></div>'+icon('arrow')+'</a>').join('')+'</div>'}
function block(id,num,title,desc,body,actions=''){return '<section class="panel workflow-block" id="'+id+'"><div class="block-heading"><span class="step-number">'+num+'</span><div><h2>'+title+'</h2><p class="sub">'+desc+'</p></div></div><div class="req-body">'+body+'</div>'+(actions?'<div class="form-footer">'+actions+'</div>':'')+'</section>'}
function missingProject(){return heading('Create your first project','Your three-phase workflow starts with a project.',button('+ New project',"openCreate('project')",true))}
function saveRequirements(){captureReq();toast('Requirements saved for this session.')}
requirementScreen=function(){if(!projectReady())return missingProject();const r=current(),disabled=r.approved?' disabled':'';if(r.approved&&!r.doc)generateDoc(r);return workflowHeader(0,'Requirements workspace','Capture the context, resolve questions, and approve your SRS.')+
block('capture','1','Project inputs','Your brief, supporting documents, and meeting context in one place.','<div class="form-grid"><label class="field">Project brief<textarea id="brief"'+disabled+'>'+esc(r.brief)+'</textarea></label><div><label class="field">Supporting documents<input type="file" accept=".txt,.md" onchange="readFile(this)"'+disabled+'></label><p class="sub">TXT or Markdown · Up to 1 MB · Read locally</p><p class="file-chip">'+icon('requirements')+' '+esc(r.source)+'</p><div class="meeting-callout"><b>Discuss it in a live meeting</b><p>Zoom with a side-by-side transcript and translation.</p><a class="text-link" href="#meetings">Open meeting workspace →</a></div></div></div><label class="field">Meeting context<textarea id="meeting"'+disabled+'>'+esc(r.meeting)+'</textarea></label>',button('Save inputs','saveRequirements()',true))+
block('clarification','2','Clarify the requirements','Answer now, or leave an explicit assumption for review.','<div class="form-grid">'+['Who can approve deliverables?','How quickly should notifications arrive?'].map((q,i)=>'<label class="field">'+q+'<textarea class="short-text" id="ans'+i+'"'+disabled+'>'+esc(r.answers[i])+'</textarea></label>').join('')+'</div>',button('Generate example SRS','buildSrs()',true))+
block('specification','3','Software requirements specification','Edit the draft directly. Example generation is not connected to an AI service.',r.doc?'<article id="srs" class="doc" contenteditable="'+!r.approved+'" aria-label="SRS document">'+r.doc+'</article>':'<div class="empty">Your SRS will appear here after you generate an example draft.</div>',button('Export SRS','exportSrs()')+button('Save document','saveRequirements()'))+
block('quality','4','Quality review','Check completeness, assumptions, and measurable acceptance criteria.','<div class="review-grid"><div><h3>Reviewer checklist</h3><p>Confirm scope, approval ownership, and notification timing with stakeholders.</p><p class="sub">Open assumptions: '+r.answers.filter(a=>!a.trim()).length+'</p></div><div><h3>Example recommendation</h3><p>Add an approval audit trail and a measurable notification target.</p>'+button(r.applied?'Wording added':'Apply proposed wording','applyRecommendation()')+'</div></div><p class="sub">'+(r.reviewed?'✓ Quality review completed.':'Human review required before approval.')+'</p>',button('Mark review complete','completeRequirementReview()',true))+
block('baseline','5','Requirements baseline','Approve and lock the SRS before moving to Planning.',r.approved?'<div class="success-strip">'+icon('check')+' Requirements Baseline Created · Approved SRS version locked</div>':'<label class="check-line"><input type="checkbox" id="approveCheck"'+(!r.reviewed?' disabled':'')+'> I have reviewed this SRS and approve its baseline.</label>',r.approved?button('Create new draft','restartRequirements()')+button('Next: Planning →',"navigate('planning')",true):button('Approve baseline','approveBaseline()',true));};
function buildSrs(){captureReq();let r=current();if(r.approved)return toast('Create a new draft first.');if(r.doc)return toast('An SRS already exists. Edit the document below.');generateDoc(r);track('Example SRS generated','Requirements');render();setTab(2)}
function completeRequirementReview(){captureReq();let r=current();if(!r.doc)return toast('Generate an SRS before reviewing.');r.reviewed=true;render();setTab(4)}
const originalRecommendation=applyRecommendation;
applyRecommendation=function(){captureReq();if(!current().doc)return toast('Generate an SRS first.');originalRecommendation()};
function restartRequirements(){delete plans[selected];delete architectures[selected];newDraft();render();toast('New requirements draft created. Downstream approvals reset.')}
function planState(){return plans[selected]??(plans[selected]={rows:[],capacity:30,weeks:4,notes:'',reviewed:false,approved:false})}
function planningScreen(){if(!projectReady())return missingProject();const r=current(),p=planState();return workflowHeader(1,'Requirement planning','Turn the approved SRS into deliverable work and a realistic plan.')+(!r.approved?'<div class="notice">Planning is available to explore. Approve the Phase 1 SRS before generating or approving a plan. <a href="#requirements">Open requirements →</a></div>':'<div class="success-strip">✓ Approved SRS baseline received from Phase 1</div>')+
block('backlog','1','Functional requirements & user stories','Review example stories, acceptance criteria, priorities, and effort.',p.rows.length?table(['ID / module','User story & acceptance criteria','Priority','Hours'],p.rows.map((row,i)=>['<b>'+row.id+'</b><small class="cell-small">'+row.module+'</small>','<label class="field"><textarea class="story-text" aria-label="Story '+row.id+'" '+(p.approved?'disabled':'')+' onchange="editStory('+i+',this.value)">'+esc(row.story)+'</textarea></label><p class="sub">'+esc(row.ac)+'</p>','<select aria-label="Priority '+row.id+'" '+(p.approved?'disabled':'')+' onchange="planState().rows['+i+'].priority=this.value;planState().reviewed=false"><option '+(row.priority==='High'?'selected':'')+'>High</option><option '+(row.priority==='Medium'?'selected':'')+'>Medium</option><option '+(row.priority==='Low'?'selected':'')+'>Low</option></select>','<input class="number-input" aria-label="Effort '+row.id+'" type="number" min="1" max="1000" value="'+row.hours+'" '+(p.approved?'disabled':'')+' onchange="editHours('+i+',this.value)">'])):'<div class="empty">Generate a sample backlog from the approved baseline, then refine each story.</div>',button('Generate example backlog','generatePlan()',true))+
block('capacity','2','Team capacity & delivery estimate','Adjust weekly capacity to see how it changes the delivery estimate.','<div class="form-grid"><label class="field">Available team hours / week<input type="number" min="1" max="10000" value="'+p.capacity+'" '+(p.approved?'disabled':'')+' onchange="updateCapacity(this.value)"></label><div class="estimate"><span>Estimated delivery</span><strong>'+Math.ceil(p.rows.reduce((n,r)=>n+r.hours,0)/p.capacity)+' weeks</strong><small>'+p.rows.reduce((n,r)=>n+r.hours,0)+' total hours / '+p.capacity+' hours per week · excludes contingency</small></div></div><label class="field">Dependencies, risks & team notes<textarea id="planNotes" '+(p.approved?'disabled':'')+'>'+esc(p.notes)+'</textarea></label>')+
block('planning-review','3','Review & planning baseline','Validate scope, estimates, capacity, and dependencies with your team.','<label class="check-line"><input type="checkbox" '+(p.reviewed?'checked':'')+' '+(p.approved?'disabled':'')+' onchange="planState().reviewed=this.checked"> I reviewed the backlog and delivery estimate.</label>'+(p.approved?'<div class="success-strip">✓ Requirement Planning Completed · Planning baseline locked</div>':''),p.approved?button('Create new planning draft','reopenPlan()')+button('Next: Architecture →',"navigate('architecture')",true):button('Approve planning baseline','approvePlan()',true));}
function generatePlan(){captureReq();const p=planState();if(!current().approved)return toast('Approve the Phase 1 baseline first.');if(p.rows.length)return toast('The backlog already exists. Edit the stories below.');p.rows=[{id:'FR-001',module:'Access',story:'As a client, I can access only my assigned projects.',ac:'Given an unassigned project, access is denied and no project data is returned.',priority:'High',hours:24},{id:'FR-002',module:'Review',story:'As a reviewer, I can submit feedback on a deliverable.',ac:'Feedback is saved with the author, deliverable, and timestamp.',priority:'High',hours:32},{id:'FR-003',module:'Notifications',story:'As a stakeholder, I am notified when a deliverable is ready.',ac:'Delivery attempts and failures are recorded for review.',priority:'Medium',hours:16}];track('Example backlog generated','Planning');render()}
function editStory(i,value){let p=planState();if(p.approved)return;p.rows[i].story=value;p.reviewed=false}
function editHours(i,value){let p=planState();if(p.approved)return;const n=Number(value);if(!Number.isFinite(n)||n<1||n>1000){toast('Enter effort between 1 and 1,000 hours.');render();return}p.rows[i].hours=n;p.reviewed=false;captureReq();render()}
function updateCapacity(value){const p=planState(),n=Number(value);if(p.approved)return;if(!Number.isFinite(n)||n<1||n>10000){toast('Enter capacity between 1 and 10,000.');render();return}captureReq();p.capacity=n;p.reviewed=false;render()}
function approvePlan(){captureReq();let p=planState();if(!current().approved||!p.rows.length||!p.reviewed)return toast('Approve the SRS, generate the backlog, and complete the review first.');p.approved=true;track('Planning baseline approved','Planning');render()}
function reopenPlan(){planState().approved=false;planState().reviewed=false;delete architectures[selected];render();toast('Planning draft opened. Architecture approval reset.')}
function architectureState(){return architectures[selected]??(architectures[selected]={doc:'',reviewed:false,approved:false})}
function architectureScreen(){if(!projectReady())return missingProject();const a=architectureState(),p=planState();return workflowHeader(2,'Architecture & validation','Connect the plan to system design, tests, and traceability.')+(!p.approved?'<div class="notice">Approve the Phase 2 planning baseline before generating the architecture. <a href="#planning">Open planning →</a></div>':'<div class="success-strip">✓ Approved planning data received from Phase 2</div>')+
block('system-design','1','System architecture','Generate an example, then adapt the system boundaries and technology decisions.',a.doc?'<div class="system-map" aria-label="System architecture: Web client calls Application API, connected to identity, database, and event queue"><div>Web client<small>Project & team workspace</small></div><span>↓</span><div>Application API<small>Authorization & workflow rules</small></div><span>↓</span><div class="map-services"><b>Identity service</b><b>Project database</b><b>Event queue</b></div></div><label class="field">Architecture decisions<textarea id="architectureDoc" '+(a.approved?'disabled':'')+'>'+esc(a.doc)+'</textarea></label>':'<div class="empty">The system design and decision record will appear here.</div>',button('Generate example architecture','generateArchitecture()',true))+
block('traceability','2','Test cases & traceability','Every planned requirement should have a design owner and a verification step.',a.doc?table(['Requirement','Design component','Test case','Expected result'],p.rows.map((r,i)=>['<b>'+r.id+'</b>',['Authorization middleware','Review service','Notification worker'][i]||'Application API','TC-00'+(i+1),esc(r.ac)])):'<div class="empty">Generate architecture to see example requirement-to-test coverage.</div>')+
block('architecture-review','3','Quality assessment & approval','Review the design, security boundaries, failures, and test coverage.','<div class="review-grid"><div><h3>Design review</h3><p>Validate tenant isolation, authorization, scalability, and recovery paths.</p></div><div><h3>Test review</h3><p>Confirm negative paths, integration tests, and measurable acceptance outcomes.</p></div></div><label class="check-line"><input type="checkbox" '+(a.reviewed?'checked':'')+' '+(a.approved?'disabled':'')+' onchange="architectureState().reviewed=this.checked"> I reviewed the architecture and test coverage.</label>'+(a.approved?'<div class="success-strip">✓ Architecture baseline approved · Ready for development handoff</div>':''),a.approved?button('Create new architecture draft','architectureState().approved=false;architectureState().reviewed=false;render()')+button('Export handoff','exportHandoff()',true):button('Approve architecture','approveArchitecture()',true));}
function generateArchitecture(){captureReq();let a=architectureState();if(!planState().approved)return toast('Approve the planning baseline first.');if(a.doc)return toast('An architecture draft already exists. Edit the decisions below.');a.doc='Example architecture for '+projects.find(p=>p.id===selected).name+'\n\nWeb application → Application API → Project database and event queue.\n\nIdentity: authenticate users and enforce workspace/project permissions at the API.\nReview service: store immutable approval decisions with author and timestamp.\nNotification worker: retry failed deliveries and retain an audit trail.\n\nOpen decisions: technology stack, deployment region, availability target, retention policy, and expected concurrency.\n\nMeeting integration: authorized Zoom media access → streaming transcription → translation → approved requirements context. Services are not connected in this prototype.';track('Example architecture generated','Architecture');render()}
function approveArchitecture(){captureReq();let a=architectureState();if(!planState().approved||!a.doc||!a.reviewed)return toast('Generate the architecture and complete the review first.');a.approved=true;track('Architecture baseline approved','Architecture');render()}
function downloadText(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportHandoff(){captureReq();downloadText('blueprint-project-handoff.json',JSON.stringify({project:projects.find(p=>p.id===selected).name,requirements:current(),planning:planState(),architecture:architectureState(),prototype:true},null,2),'application/json')}
const meetingLines=[['Sahim','Clients should only see projects assigned to their organization.','ক্লায়েন্টরা শুধু তাদের প্রতিষ্ঠানের নির্ধারিত প্রকল্প দেখতে পারবেন।','Los clientes solo deben ver los proyectos asignados a su organización.'],['Maya','We also need a clear approval owner for each deliverable.','প্রতিটি ডেলিভারেবলের জন্য একজন নির্দিষ্ট অনুমোদনকারী প্রয়োজন।','También necesitamos un responsable de aprobación para cada entregable.'],['Alex','Every approval should include the reviewer and timestamp.','প্রতিটি অনুমোদনে পর্যালোচক এবং সময় উল্লেখ থাকতে হবে।','Cada aprobación debe incluir el revisor y la fecha y hora.']];
function meetingScreen(){if(!projectReady())return missingProject();return heading('Live meeting workspace','Keep the conversation, transcript, and translation together.',projectPicker())+'<div class="notice"><b>Zoom is not connected.</b> Live transcription and translation need an authorized meeting integration and processing services. The preview below uses prerecorded sample text.</div>'+panel('Meeting setup','<div class="req-body"><div class="form-grid"><label class="field">Zoom link<input id="meetLink" type="url" value="'+esc(meetLinkValue)+'" oninput="meetLinkValue=this.value" placeholder="https://zoom.us/j/12345678901"></label><div class="form-grid"><label class="field">Spoken language<select disabled><option>English</option></select></label><label class="field">Translate into<select onchange="meetingDemo.target=this.value;updateTranscript()"><option value="bn" '+(meetingDemo.target==='bn'?'selected':'')+'>বাংলা · Bengali</option><option value="es" '+(meetingDemo.target==='es'?'selected':'')+'>Español · Spanish</option></select></label></div></div><div class="actions">'+button('Open Zoom','openMeet()',true)+button('Connection requirements','meetingConnection()')+'</div></div>')+'<div class="meeting-stage"><div><span class="badge">'+(meetingDemo.running?'Sample playback running':'Preview ready')+'</span><h2>Discovery conversation</h2><p>Transcript and translation stay aligned as each speaker finishes.</p></div><div class="actions">'+button(meetingDemo.running?'Pause sample':'Play sample transcript','toggleMeetingDemo()',true)+button('Reset','resetMeetingDemo()')+'</div></div><div class="transcript-grid">'+panel('Original transcript · English','<div class="transcript" id="originalTranscript"></div>')+panel('Translation · Sample text','<div class="transcript" id="translatedTranscript"></div>')+'</div><div class="meeting-footer"><p class="sub">Review the transcript before adding it to requirements. No meeting audio is captured.</p><div class="actions">'+button('Export transcript','exportMeeting()')+button('Add to requirements','useMeeting()',true)+'</div></div>';}
function openMeet(){const v=document.getElementById('meetLink')?.value.trim()||'';try{const u=new URL(v);if(u.protocol!=='https:'||!(u.hostname==='zoom.us'||u.hostname.endsWith('.zoom.us'))||!/^\/(?:j\/\d{9,11}|my\/[a-zA-Z0-9._-]+)\/?$/.test(u.pathname))throw Error();window.open(u.href,'_blank','noopener,noreferrer')}catch{toast(document.documentElement.lang==='ja'?'有効なZoom会議リンクを入力してください。':'Enter a valid Zoom meeting link, such as https://zoom.us/j/12345678901.')}}
function meetingConnection(){modal('Connect live meeting services','<p>To process a real meeting, this app needs:</p><ol><li>Authorized Zoom media access or a meeting transcription provider.</li><li>A backend for streaming transcription and translation.</li><li>Participant consent and a retention policy.</li></ol><p>No service is connected. Opening a Zoom link does not start capture.</p><a class="text-link" target="_blank" rel="noopener" href="https://developers.zoom.us/docs/rtms/meetings/">Zoom integration requirements ↗</a>',"event.preventDefault();document.getElementById('modal').close()")}
function updateTranscript(){if(!$('#originalTranscript'))return;['originalTranscript','translatedTranscript'].forEach((id,j)=>{$('#'+id).innerHTML=meetingDemo.lines.length?meetingDemo.lines.map((i)=>'<div class="utterance"><div>'+avatar(meetingLines[i][0])+'<b>'+meetingLines[i][0]+'</b><small>00:'+String(i*8).padStart(2,'0')+' · Sample</small></div><p>'+esc(meetingLines[i][j?(meetingDemo.target==='bn'?2:3):1])+'</p></div>').join(''):'<div class="empty">Play the sample to preview '+(j?'translation':'transcription')+'.</div>'})}
function toggleMeetingDemo(){if(meetingDemo.running){clearInterval(meetingDemo.timer);meetingDemo.running=false;render();return}if(meetingDemo.lines.length===meetingLines.length)meetingDemo.lines=[];meetingDemo.project=selected;meetingDemo.running=true;const tick=()=>{meetingDemo.lines.push(meetingDemo.lines.length);if(meetingDemo.lines.length===meetingLines.length){clearInterval(meetingDemo.timer);meetingDemo.running=false;if(screen==='meetings')render()}else updateTranscript()};meetingDemo.timer=setInterval(tick,1800);render();tick()}
function resetMeetingDemo(){clearInterval(meetingDemo.timer);meetingDemo.lines=[];meetingDemo.running=false;render()}
function exportMeeting(){if(!meetingDemo.lines.length)return toast('Play the sample transcript first.');downloadText('meeting-sample-transcript.txt',meetingDemo.lines.map(i=>meetingLines[i][0]+': '+meetingLines[i][1]+'\n'+meetingLines[i][meetingDemo.target==='bn'?2:3]).join('\n\n'))}
function useMeeting(){if(!meetingDemo.lines.length)return toast('Play the sample transcript first.');if(current().approved)return toast('Create a new requirements draft before adding meeting context.');current().meeting=meetingDemo.lines.map(i=>meetingLines[i][0]+': '+meetingLines[i][1]).join('\n');track('Sample meeting context added','Requirements');navigate('requirements');toast('Sample transcript added. Review it in Project inputs.')}
function bars(values,labels){const max=Math.max(1,...values);return '<div class="bar-chart" role="img" aria-label="'+esc(labels.map((l,i)=>l+': '+values[i]).join(', '))+'">'+values.map((v,i)=>'<div class="bar-column"><b>'+v+'</b><div class="bar-track"><i style="height:'+Math.max(2,v/max*100)+'%"></i></div><small>'+labels[i]+'</small></div>').join('')+'</div>'}
function lineChart(){const v=chartRange===7?[12,21,17,33,29,42,51]:[34,52,47,76,88,105,126];return '<svg class="line-chart" viewBox="0 0 600 210" role="img" aria-label="Illustrative activity trend: '+v.join(', ')+' actions"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6d5ce7" stop-opacity=".22"/><stop offset="1" stop-color="#6d5ce7" stop-opacity="0"/></linearGradient></defs>'+[30,75,120,165].map((y,i)=>'<line x1="35" y1="'+y+'" x2="580" y2="'+y+'" stroke="#e8ebf3"/><text x="0" y="'+(y+5)+'">'+[60,40,20,0][i]+'</text>').join('')+'<path d="M40 140 L130 117 L220 127 L310 87 L400 97 L490 64 L580 42 L580 165 L40 165Z" fill="url(#area)"/><path d="M40 140 L130 117 L220 127 L310 87 L400 97 L490 64 L580 42" fill="none" stroke="#6755db" stroke-width="3"/>'+['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((l,i)=>'<text x="'+(30+i*90)+'" y="198">'+l+'</text>').join('')+'</svg><p class="chart-note">Illustrative 7-day activity · Example data</p>'}
dashboard=function(){const ps=projects.filter(p=>p.space===workspace),events=usageEvents.filter(e=>e.space===workspace),approved=ps.filter(p=>reqs[p.id]?.approved||p.status==='Approved').length;return heading('Workspace overview','Your projects, decisions, and team activity at a glance.',button('+ New project',"openCreate('project')",true))+'<div class="metrics">'+[['Active projects',ps.length,'projects'],['SRS baselines',approved,'requirements'],['Planning baselines',ps.filter(p=>plans[p.id]?.approved).length,'planning'],['Architecture baselines',ps.filter(p=>architectures[p.id]?.approved).length,'architecture']].map(([label,n,i])=>'<div class="metric"><div class="metric-top">'+label+'<span class="metric-icon">'+icon(i)+'</span></div><strong>'+n+'</strong><small>Current workspace</small></div>').join('')+'</div><div class="dashboard-charts">'+panel('Workspace activity',workspace===0?lineChart():'<div class="empty">No activity history yet.</div>','<span class="badge gray">Sample history</span>')+panel('Approved baselines by phase',bars([approved,ps.filter(p=>plans[p.id]?.approved).length,ps.filter(p=>architectures[p.id]?.approved).length],['Requirements','Planning','Architecture']),'','Current workspace state')+'</div>'+panel('Your projects',projectTable(),'<a class="text-link" href="#projects">View all →</a>')+'<div class="bottom-grid">'+panel('Continue your workflow','<div class="quick-actions"><a href="#requirements"><span class="step-number">01</span><div><b>Capture & approve requirements</b><small>Brief, documents, meeting context, and SRS</small></div>'+icon('arrow')+'</a><a href="#planning"><span class="step-number">02</span><div><b>Plan the delivery</b><small>Stories, effort, capacity, and dependencies</small></div>'+icon('arrow')+'</a><a href="#architecture"><span class="step-number">03</span><div><b>Design & validate</b><small>Architecture, tests, and traceability</small></div>'+icon('arrow')+'</a></div>')+panel('Usage this session','<div class="req-body"><div class="usage-total"><strong>'+events.length+'</strong><span>tracked actions</span></div><p class="sub">Real AI tokens, meeting minutes, and billing are not connected.</p><a class="text-link" href="#usage">View usage details →</a></div>')+'</div>'};
function usageScreen(){const events=usageEvents.filter(e=>e.space===workspace);return heading('Usage & consumption','Understand activity across your workspace.',button('Export activity CSV','exportUsage()'))+'<div class="notice">Session activity is tracked locally. AI token usage, live meeting minutes, translation characters, and billing require connected services.</div><div class="metrics">'+[['Tracked actions',events.length],['AI tokens','—'],['Live meeting minutes','—'],['Translation characters','—']].map(([t,n],i)=>'<div class="metric"><div class="metric-top">'+t+'</div><strong>'+n+'</strong><small>'+(i?'Not connected':'This session · This workspace')+'</small></div>').join('')+'</div>'+panel('Actions by phase',bars(['Requirements','Planning','Architecture'].map(p=>events.filter(e=>e.phase===p).length),['Requirements','Planning','Architecture']))+panel('Activity log',table(['Time','Project','Phase','Action'],events.slice().reverse().map(e=>[e.time,esc(projects.find(p=>p.id===e.project)?.name||'Project'),e.phase,esc(e.action)])),'','Session activity; sample generations are labeled')}
function exportUsage(){let rows=[['Time','Project','Phase','Action'],...usageEvents.filter(e=>e.space===workspace).map(e=>[e.time,projects.find(p=>p.id===e.project)?.name,e.phase,e.action])];downloadText('blueprint-session-usage.csv',rows.map(r=>r.map(v=>'"'+String(v||'').replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv')}
const renderBase=render;
render=function(){renderBase();if(screen==='meetings')updateTranscript()};
const originalApprove=approveBaseline;
approveBaseline=function(){captureReq();const before=current().approved;originalApprove();if(!before&&current().approved)track('Requirements baseline approved','Requirements')};
render();
